assignments.requirements:
- Module `commands.py` with `class CommandError(Exception)`, an abstract `Command` (`abc.ABC`) with abstract `matches(self, user_input: str) -> bool` and `execute(self, user_input: str) -> str`.
- `CommandExecutor(commands: Sequence[Command])` with `execute(user_input: str) -> str`:
  - runs the **first** matching command and returns its result;
  - if a command raises `CommandError`, return `f"Error: {message}"`;
  - if nothing matches (including empty or whitespace-only input) return `"Invalid command"`;
  - any other exception propagates.
- `RegisterUser(directory: dict[str, str], hasher: Callable[[str], str])` handles `register <name> <phone> <password>` (case-insensitive keyword, single-space or multi-space separated). `name` is `\w+`, `phone` is exactly 10 digits, `password` has no spaces. It stores `directory[phone] = hasher(password)` and returns `"Registered <name>"`. A phone that is already in `directory` raises `CommandError("phone already registered")`. The plain password must never be stored.
- `SettleUpUser(settle: Callable[[int], list[str]])` handles `u<digits> settleup` (exactly two words; keyword case-insensitive; `u` case-insensitive; the rest of the first word digits only). It calls `settle(user_id)` and returns the lines joined by `"\n"`, or `"Nothing to settle"` if the list is empty.
- Matching must be exact: `"u1 SettleUp now"`, `"g1 SettleUp"`, `"register asha 123 pw"` and `"registerx asha 9876543210 pw"` do **not** match.

assignments.referenceSolution:
The executor knows only the `Command` abstraction, so new features are new classes. Strict matchers (`fullmatch`, token checks) keep first-match-wins dispatch predictable, and the single `except CommandError` turns expected domain failures into messages while letting real bugs propagate.

**`commands.py`**

```python
import re
from abc import ABC, abstractmethod
from collections.abc import Callable, Sequence


class CommandError(Exception):
    pass


class Command(ABC):
    @abstractmethod
    def matches(self, user_input: str) -> bool: ...

    @abstractmethod
    def execute(self, user_input: str) -> str: ...


class CommandExecutor:
    def __init__(self, commands: Sequence[Command]) -> None:
        self.commands = list(commands)

    def execute(self, user_input: str) -> str:
        for command in self.commands:
            if command.matches(user_input):
                try:
                    return command.execute(user_input)
                except CommandError as exc:
                    return f"Error: {exc}"
        return "Invalid command"


class RegisterUser(Command):
    _RE = re.compile(
        r"register\s+(?P<name>\w+)\s+(?P<phone>\d{10})\s+(?P<password>\S+)",
        re.IGNORECASE,
    )

    def __init__(self, directory: dict[str, str], hasher: Callable[[str], str]) -> None:
        self.directory = directory
        self.hasher = hasher

    def matches(self, user_input: str) -> bool:
        return self._RE.fullmatch(user_input.strip()) is not None

    def execute(self, user_input: str) -> str:
        m = self._RE.fullmatch(user_input.strip())
        if m is None:
            raise CommandError("malformed register command")
        phone = m["phone"]
        if phone in self.directory:
            raise CommandError("phone already registered")
        self.directory[phone] = self.hasher(m["password"])
        return f"Registered {m['name']}"


class SettleUpUser(Command):
    def __init__(self, settle: Callable[[int], list[str]]) -> None:
        self.settle = settle

    def matches(self, user_input: str) -> bool:
        words = user_input.split()
        return (
            len(words) == 2
            and words[1].lower() == "settleup"
            and words[0][:1].lower() == "u"
            and words[0][1:].isdigit()
        )

    def execute(self, user_input: str) -> str:
        user_id = int(user_input.split()[0][1:])
        lines = self.settle(user_id)
        return "\n".join(lines) if lines else "Nothing to settle"
```

**`test_commands.py`**

```python
import pytest

from commands import Command, CommandError, CommandExecutor, RegisterUser, SettleUpUser


def make():
    directory: dict[str, str] = {}
    calls: list[int] = []

    def settle(uid: int) -> list[str]:
        calls.append(uid)
        return [f"u{uid} pays u2 100", "u3 pays u1 50"] if uid == 1 else []

    executor = CommandExecutor(
        [RegisterUser(directory, hasher=lambda pw: "h:" + pw[::-1]), SettleUpUser(settle)]
    )
    return executor, directory, calls


def test_register_and_duplicate_phone():
    executor, directory, _ = make()
    assert executor.execute("Register asha 9876543210 s3cret") == "Registered asha"
    assert directory == {"9876543210": "h:terc3s"}          # hashed, never plain
    assert executor.execute("  REGISTER ravi   9876543210  pw ") == "Error: phone already registered"
    assert list(directory) == ["9876543210"]


def test_settle_up_user_output():
    executor, _, calls = make()
    assert executor.execute("u1 SettleUp") == "u1 pays u2 100\nu3 pays u1 50"
    assert executor.execute("U7 SETTLEUP") == "Nothing to settle"
    assert calls == [1, 7]


@pytest.mark.parametrize(
    "text",
    [
        "",
        "   ",
        "u1 SettleUp now",
        "g1 SettleUp",
        "u SettleUp",
        "u1x SettleUp",
        "register asha 123 pw",
        "registerx asha 9876543210 pw",
        "register asha 9876543210",
        "delete g1",
    ],
)
def test_strict_matching(text):
    executor, directory, calls = make()
    assert executor.execute(text) == "Invalid command"
    assert directory == {} and calls == []


def test_first_match_wins_and_new_commands_need_no_executor_change():
    class Help(Command):
        def matches(self, user_input: str) -> bool:
            return user_input.strip().lower() == "help"

        def execute(self, user_input: str) -> str:
            return "commands: register, settleup"

    class Greedy(Command):
        def matches(self, user_input: str) -> bool:
            return True

        def execute(self, user_input: str) -> str:
            return "greedy"

    assert CommandExecutor([Help(), Greedy()]).execute("HELP") == "commands: register, settleup"
    assert CommandExecutor([Greedy(), Help()]).execute("help") == "greedy"


def test_only_command_errors_are_converted():
    class Boom(Command):
        def matches(self, user_input: str) -> bool:
            return True

        def execute(self, user_input: str) -> str:
            raise ZeroDivisionError

    class Soft(Boom):
        def execute(self, user_input: str) -> str:
            raise CommandError("nope")

    assert CommandExecutor([Soft()]).execute("x") == "Error: nope"
    with pytest.raises(ZeroDivisionError):
        CommandExecutor([Boom()]).execute("x")


def test_command_is_abstract():
    with pytest.raises(TypeError):
        Command()
```

